(async () => {
  await nav('Standings')
  await switchTo('NCAA Men')
  await chooseSelect('Season', 2026)
  await sleep(4000)
  const t = mainText()
  const heads = [...document.querySelectorAll('thead th,[role=columnheader]')].map((x) => x.textContent.replace(/[▲▼]/g, '').trim())
  const rs = [...document.querySelectorAll('[role=row]')].filter((r) => r.querySelector('[role=cell]')).map((r) => [...r.querySelectorAll('[role=cell]')].map((c) => c.textContent.trim()))
  // SRS is the third cell from the end of a row, a signed number with two decimals.
  const filled = rs.filter((c) => /^[+\u2212-]\d+\.\d\d$/.test(c[c.length - 3] ?? '')).length
  const ok = !bad(t) && ['SRS', 'ELO', 'PYTH W'].every((h) => heads.includes(h)) && rs.length > 340 && filled === rs.length && /Division I teams alone/.test(t) && !/PLAYOFF%/.test(heads.join(' '))
  return check('NCAA Men standings 2025-26: SRS, SOS, Elo and Pythagorean wins on every team, the note on Division I games, no forecast columns', ok, { heads: heads.slice(0, 20), filled, rows: rs.length, first: rs[0], note: t.slice(t.indexOf('PYTH W, SRS'), t.indexOf('PYTH W, SRS') + 260) })
})()

